    13→
    14→namespace Nethermind.Blockchain.Tracing;
    15→
    16→public class BlockReceiptsTracer : IBlockTracer, ITxTracer, IJournal<int>, ITxTracerWrapper
    17→{
    18→    private IBlockTracer _otherTracer = NullBlockTracer.Instance;
    19→    protected Block Block = null!;
    20→    public bool IsTracingReceipt => true;
    21→    public bool IsTracingActions => _currentTxTracer.IsTracingActions;
    22→    public bool IsTracingOpLevelStorage => _currentTxTracer.IsTracingOpLevelStorage;
    23→    public bool IsTracingMemory => _currentTxTracer.IsTracingMemory;
    24→    public bool IsTracingInstructions => _currentTxTracer.IsTracingInstructions;
    25→    public bool IsTracingRefunds => _currentTxTracer.IsTracingRefunds;
    26→    public bool IsTracingCode => _currentTxTracer.IsTracingCode;
    27→    public bool IsTracingStack => _currentTxTracer.IsTracingStack;
    28→    public bool IsTracingState => _currentTxTracer.IsTracingState;
    29→    public bool IsTracingStorage => _currentTxTracer.IsTracingStorage;
    30→
    31→    public bool IsTracingBlockHash => _currentTxTracer.IsTracingBlockHash;
    32→    public bool IsTracingAccess => _currentTxTracer.IsTracingAccess;
    33→    public bool IsTracingFees => _currentTxTracer.IsTracingFees;
    34→    public bool IsTracingLogs => _currentTxTracer.IsTracingLogs;
    35→
    36→    public void MarkAsSuccess(Address recipient, GasConsumed gasSpent, byte[] output, LogEntry[] logs, Hash256? stateRoot = null)
    37→    {
    38→        _txReceipts.Add(BuildReceipt(recipient, gasSpent.SpentGas, StatusCode.Success, logs, stateRoot));
    39→
    40→        // hacky way to support nested receipt tracers
    41→        if (_otherTracer is ITxTracer otherTxTracer)
    42→        {
    43→            otherTxTracer.MarkAsSuccess(recipient, gasSpent, output, logs, stateRoot);
    44→        }
    45→
    46→        if (_currentTxTracer.IsTracingReceipt)
    47→        {
    48→            _currentTxTracer.MarkAsSuccess(recipient, gasSpent, output, logs, stateRoot);
    49→        }
    50→    }
    51→
